import { toAddress } from './address.js'

const FAIL = new Error('grammar')

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ k: 'word', v: m[0].toUpperCase() }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[=<>^*\/+\-(),:])/.exec(s.slice(i)))) { toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue }
    throw FAIL
  }
  return toks
}

// Returns an AST, or null when the grammar rejects the formula.
// A formula whose only problem is a misplaced range yields {t:'err'} wrapping nothing useful,
// but deps still needs its cells: ranges parse as nodes and are checked after parsing.
export function parseFormula(body) {
  try {
    const toks = tokenize(body)
    let p = 0
    const peek = () => toks[p]
    const isOp = (v) => toks[p] && toks[p].k === 'op' && toks[p].v === v
    const expectOp = (v) => { if (!isOp(v)) throw FAIL; p++ }
    const CMP = ['=', '<>', '<', '<=', '>', '>=']
    function cmp() {
      let l = add()
      while (peek() && peek().k === 'op' && CMP.includes(peek().v)) { const op = toks[p++].v; l = { t: 'bin', op, l, r: add() } }
      return l
    }
    function add() {
      let l = mul()
      while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: mul() } }
      return l
    }
    function mul() {
      let l = pow()
      while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: pow() } }
      return l
    }
    function pow() {
      const l = unary()
      if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
      return l
    }
    function unary() {
      if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
      return primary()
    }
    function primary() {
      const t = peek()
      if (!t) throw FAIL
      if (t.k === 'num') { p++; return { t: 'num', v: t.v } }
      if (isOp('(')) { p++; const e = cmp(); expectOp(')'); return e }
      if (t.k === 'word') {
        p++
        if (isOp('(')) {
          p++
          const args = []
          if (!isOp(')')) {
            for (;;) {
              args.push(arg())
              if (isOp(',')) { p++; continue }
              break
            }
          }
          expectOp(')')
          return { t: 'call', name: t.v, args }
        }
        if (t.v === 'TRUE') return { t: 'bool', v: true }
        if (t.v === 'FALSE') return { t: 'bool', v: false }
        return { t: 'ref', addr: toAddress(t.v) }
      }
      throw FAIL
    }
    function arg() {
      const t = peek()
      if (t && t.k === 'word' && toks[p + 1] && toks[p + 1].k === 'op' && toks[p + 1].v === ':') {
        const n = toks[p + 2]
        if (!n || n.k !== 'word') throw FAIL
        p += 3
        return { t: 'range', a: toAddress(t.v), b: toAddress(n.v) }
      }
      return cmp()
    }
    const e = cmp()
    if (p !== toks.length) throw FAIL
    return e
  } catch (e) {
    if (e === FAIL) return null
    throw e
  }
}
