import { toAddress } from './address.js'

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*/.exec(line)
    const word = m[1].toUpperCase()
    const addr = toAddress(word)
    if (!addr) throw new Error(`error: line ${i + 1}: invalid cell address ${word}`)
    if (seen.has(addr.key)) throw new Error(`error: line ${i + 1}: cell ${addr.name} is declared twice`)
    seen.add(addr.key)
    cells.push({ ...addr, content: line.slice(m[0].length) })
  })
  cells.sort((a, b) => a.col - b.col || a.row - b.row)
  return cells
}
