export function colName(c) {
  return c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26))
}
// Returns {col,row,key,name} or null when not a valid address.
export function toAddress(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  const col = L.length === 1 ? L.charCodeAt(0) - 64 : (L.charCodeAt(0) - 64) * 26 + L.charCodeAt(1) - 64
  return { col, row, key: col * 1000 + row, name: L + row }
}
export function expand(a, b) {
  const out = []
  const c1 = Math.min(a.col, b.col), c2 = Math.max(a.col, b.col)
  const r1 = Math.min(a.row, b.row), r2 = Math.max(a.row, b.row)
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) out.push({ col: c, row: r, key: c * 1000 + r, name: colName(c) + r })
  return out
}
