import { expand } from './address.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ k: 'err', v: e })
const num = (v) => ({ k: 'num', v })
const bool = (v) => ({ k: 'bool', v })
const text = (v) => ({ k: 'text', v })

export function formatValue(v) {
  switch (v.k) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'err': return v.v
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function literal(s) {
  if (s === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return num(Number(s))
  if (ERRORS.includes(s)) return err(s)
  return text(s)
}

const toNum = (v) => (v.k === 'bool' ? num(v.v ? 1 : 0) : v.k === 'text' ? err('#VALUE!') : v)
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

function cmpCP(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
const rank = { num: 0, text: 1, bool: 2 }

export function evaluateAll(cells) {
  const byKey = new Map(cells.map((c) => [c.key, c]))
  const memo = new Map()
  const busy = new Set()

  function cellValue(addr) {
    const c = byKey.get(addr.key)
    if (!c) return num(0)
    if (memo.has(c.key)) return memo.get(c.key)
    if (busy.has(c.key)) return err('#CYCLE!')
    busy.add(c.key)
    let v
    if (!c.content.startsWith('=')) v = literal(c.content)
    else if (!c.ast) v = err('#ERR!')
    else v = ev(c.ast)
    busy.delete(c.key)
    memo.set(c.key, v)
    return v
  }

  // Values of one argument: array of values, ranges expanded.
  function argValues(a) {
    if (a.t === 'range') {
      if (!a.a || !a.b) return [err('#REF!')]
      return expand(a.a, a.b).map(cellValue)
    }
    return [ev(a)]
  }

  function ev(n) {
    switch (n.t) {
      case 'num': return num(n.v)
      case 'bool': return bool(n.v)
      case 'ref': return n.addr ? cellValue(n.addr) : err('#REF!')
      case 'range': return err('#ERR!')
      case 'un': {
        const e = ev(n.e)
        if (e.k === 'err') return e
        const x = toNum(e)
        if (x.k === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': return binary(n)
      case 'call': return call(n)
    }
  }

  function binary(n) {
    const l = ev(n.l), r = ev(n.r)
    if (l.k === 'err') return l
    if (r.k === 'err') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      let d
      if (l.k !== r.k) d = rank[l.k] - rank[r.k]
      else if (l.k === 'text') d = cmpCP(l.v, r.v)
      else d = Number(l.v) - Number(r.v)
      if (l.k === r.k && l.k === 'num') d = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
      switch (n.op) {
        case '=': return bool(d === 0)
        case '<>': return bool(d !== 0)
        case '<': return bool(d < 0)
        case '<=': return bool(d <= 0)
        case '>': return bool(d > 0)
        default: return bool(d >= 0)
      }
    }
    const a = toNum(l)
    if (a.k === 'err') return a
    const b = toNum(r)
    if (b.k === 'err') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
      case '*': return finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
      default: return finite(Math.pow(a.v, b.v))
    }
  }

  function call(n) {
    const N = n.args.length
    const name = n.name
    const agg = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (agg.includes(name)) { if (N < 1) return err('#ERR!') }
    else if (name === 'ABS') { if (N !== 1) return err('#ERR!') }
    else if (name === 'IF') { if (N !== 3) return err('#ERR!') }
    else return err('#NAME?')

    if (name === 'IF') {
      const one = (a) => {
        const vs = argValues(a)
        const e = vs.find((v) => v.k === 'err')
        return e || (vs.length === 1 ? vs[0] : err('#VALUE!'))
      }
      const c = one(n.args[0])
      if (c.k === 'err') return c
      let t
      if (c.k === 'bool') t = c.v
      else if (c.k === 'num') t = c.v !== 0
      else return err('#VALUE!')
      return one(n.args[t ? 1 : 2])
    }
    const vals = []
    for (const a of n.args) vals.push(...argValues(a))
    const e = vals.find((v) => v.k === 'err')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.k === 'num').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.k === 'err') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'ABS': return nums.length === 1 ? num(Math.abs(nums[0])) : err('#VALUE!')
      case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return num(nums.reduce((s, x) => Math.min(s, x), Infinity))
      case 'MAX': return num(nums.reduce((s, x) => Math.max(s, x), -Infinity))
      default: return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }

  for (const c of cells) cellValue(c)
  return memo
}
